        )

    if self.modify_server_default is not False:
        col_diff.append(
            (
                "modify_default",
                schema,
                tname,
                cname,
                {
                    "existing_nullable": self.existing_nullable,
                    "existing_type": self.existing_type,
                    "existing_comment": self.existing_comment,
                },
                self.existing_server_default,
