def _create_method_proxy(cls, name, globals_, locals_):
    fn = getattr(cls, name)

    def _name_error(name, from_):
        raise NameError(
            "Can't invoke function '%s', as the proxy object has "
            "not yet been "
            "established for the Alembic '%s' class.  "
            "Try placing this code inside a callable."
            % (name, cls.__name__)
        ) from from_

    globals_["_name_error"] = _name_error

    translations = getattr(fn, "_legacy_translations", [])
    if translations:
        spec = inspect_getfullargspec(fn)
        if spec[0] and spec[0][0] == "self":
            spec[0].pop(0)

        outer_args = inner_args = "*args, **kw"
        translate_str = "args, kw = _translate(%r, %r, %r, args, kw)" % (
            fn.__name__,
            tuple(spec),
            translations,
        )

        def translate(fn_name, spec, translations, args, kw):
            return_kw = {}
            return_args = []

            for oldname, newname in translations:
                if oldname in kw:
                    warnings.warn(
                        "Argument %r is now named %r "
                        "for method %s()." % (oldname, newname, fn_name)
                    )
                    return_kw[newname] = kw.pop(oldname)
            return_kw.update(kw)

            args = list(args)
            if spec[3]:
                pos_only = spec[0][: -len(spec[3])]
            else:
                pos_only = spec[0]
            for arg in pos_only:
                if arg not in return_kw:
                    try:
                        return_args.append(args.pop(0))
                    except IndexError:
                        raise TypeError(
                            "missing required positional argument: %s"
                            % arg
                        )
            return_args.extend(args)

            return return_args, return_kw

        globals_["_translate"] = translate
    else:
        outer_args = "*args, **kw"
        inner_args = "*args, **kw"
        translate_str = ""

    func_text = textwrap.dedent(
        """\
    def %(name)s(%(args)s):
        %(doc)r
        %(translate)s
        try:
            p = _proxy
        except NameError as ne:
            _name_error('%(name)s', ne)
        return _proxy.%(name)s(%(apply_kw)s)
        e
    """
        % {
            "name": name,
            "translate": translate_str,
            "args": outer_args,
            "apply_kw": inner_args,
            "doc": fn.__doc__,
        }
    )
    lcl = {}

    exec(func_text, globals_, lcl)
    return lcl[name]

def translate(fn_name, spec, translations, args, kw):
    return_kw = {}
    return_args = []

    for oldname, newname in translations:
        if oldname in kw:
            warnings.warn(
                "Argument %r is now named %r "
                "for method %s()." % (oldname, newname, fn_name)
            )
            return_kw[newname] = kw.pop(oldname)
    return_kw.update(kw)

    args = list(args)
    if spec[3]:
        pos_only = spec[0][: -len(spec[3])]
    else:
        pos_only = spec[0]
    for arg in pos_only:
        if arg not in return_kw:
            try:
                return_args.append(args.pop(0))
            except IndexError:
                raise TypeError(
                    "missing required positional argument: %s"
                    % arg
                )
    return_args.extend(args)

    return return_args, return_kw

